import '../models/animal_reproduction_data.dart';
class ReproductionMetrics { const ReproductionMetrics({required this.services,required this.diagnoses,required this.pregnancies,required this.calvings,required this.abortions,required this.conceptionRate,required this.servicesPerConception,required this.upcoming}); final int services,diagnoses,pregnancies,calvings,abortions; final double conceptionRate,servicesPerConception; final List<AnimalReproductionData> upcoming;}
class ReproductionMetricsService { const ReproductionMetricsService(); ReproductionMetrics calculate(List<AnimalReproductionData> records){final services=records.where((e)=>{'ai','iatf','natural_service'}.contains(e.eventCode)).length;final diagnoses=records.where((e)=>e.eventCode=='pregnancy_diagnosis').length;final pregnancies=records.where((e)=>e.reproductiveStatus=='pregnant'&&e.eventCode=='pregnancy_diagnosis').length;final calvings=records.where((e)=>e.eventCode=='calving').length;final abortions=records.where((e)=>e.eventCode=='abortion').length;final now=DateTime.now();final upcoming=records.where((e){final p=e.expectedDate.split('/');if(p.length!=3)return false;final d=DateTime(int.parse(p[2]),int.parse(p[1]),int.parse(p[0]));return !d.isBefore(DateTime(now.year,now.month,now.day));}).toList()..sort((a,b)=>a.expectedDate.compareTo(b.expectedDate));return ReproductionMetrics(services:services,diagnoses:diagnoses,pregnancies:pregnancies,calvings:calvings,abortions:abortions,conceptionRate:services==0?0:pregnancies*100/services,servicesPerConception:pregnancies==0?0:services/pregnancies,upcoming:upcoming);}}
